class Solution:
    def canPartition(self, nums: List[int]) -> bool:
        total = sum(nums)
        if total % 2:
            return False
        target = total // 2
        dp = [False] * (target + 1)              # dp[s]: some subset sums to s
        dp[0] = True
        for x in nums:
            for s in range(target, x - 1, -1):   # downwards: each number is used at most once
                dp[s] = dp[s] or dp[s - x]
        return dp[target]
